export interface SonarIssue {
  rule: string;
  severity: 'BLOCKER' | 'CRITICAL' | 'MAJOR' | 'MINOR';
  message: string;
  file: string;
  line: number;
}

export function analyzeDiffForSonarIssues(diffText: string, filename: string): SonarIssue[] {
  const issues: SonarIssue[] = [];
  const lines = diffText.split('
');

  lines.forEach((line, idx) => {
    if (!line.startsWith('+') || line.startsWith('+++')) return;
    const content = line.substring(1);

    // Rule S2068: Hardcoded Credentials
    if (/(api[_-]?key|password|secret|auth[_-]?token)\s*[:=]\s*['"][A-Za-z0-9_\-]{16,}['"]/i.test(content)) {
      issues.push({
        rule: 'S2068',
        severity: 'BLOCKER',
        message: 'Hard-coded credential detected in added line.',
        file: filename,
        line: idx + 1
      });
    }

    // Rule S3649: SQL Injection Sink
    if (/SELECT\s+.*\s+FROM\s+.*\+\s*[a-zA-Z0-9_]+/i.test(content)) {
      issues.push({
        rule: 'S3649',
        severity: 'BLOCKER',
        message: 'SQL query built via string concatenation. Potential SQL injection sink.',
        file: filename,
        line: idx + 1
      });
    }
  });

  return issues;
}

import numpy as np
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge
import joblib

class HouseValuationModel:
    def __init__(self, alpha=10.0):
        self.pipeline = Pipeline([
            ("scaler", StandardScaler()),
            ("ridge", Ridge(alpha=alpha))
        ])

    def fit(self, X, y):
        # Log-transform target price to stabilize variance
        y_log = np.log1p(y)
        self.pipeline.fit(X, y_log)
        return self

    def predict(self, X):
        pred_log = self.pipeline.predict(X)
        # Invert log transformation
        return np.expm1(pred_log)

    def explain(self, x_single):
        coefs = self.pipeline.named_steps["ridge"].coef_
        intercept = self.pipeline.named_steps["ridge"].intercept_
        return {"base_log": intercept, "coefficients": coefs}

import pandas as pd
import numpy as np
from sklearn.linear_model import LogisticRegression

def preprocess_passenger(pclass, sex, age, sibsp=0, parch=0):
    # Feature engineering: family size
    family_size = sibsp + parch + 1
    is_alone = 1 if family_size == 1 else 0

    # Categorical encoding
    is_female = 1 if sex.lower() == "female" else 0

    return np.array([[pclass, is_female, age, family_size, is_alone]])

class TitanicClassifier:
    def __init__(self):
        self.model = LogisticRegression(C=1.0, solver="lbfgs")

    def predict_survival(self, features):
        prob = self.model.predict_proba(features)[0][1]
        survived = bool(prob >= 0.5)
        return {"survival_probability": round(prob, 4), "predicted_survived": survived}
